public class Main {
    public static void main(String[] args) {
        int nilai = 68;

        if (nilai >= 85) {
            System.out.println("Nilai: A");
        } else if (nilai >= 70) {
            System.out.println("Nilai: B");
        } else if (nilai >= 55) {
            System.out.println("Nilai: C");
        } else {
            System.out.println("Nilai: D");
        }
    }
}

